mapper.select:
SELECT wallet_id, user_id, balance, frozen_amount, version, created_at, updated_at
FROM user_wallet
WHERE user_id = #{userId}

mapper.update:
UPDATE user_wallet
SET balance = #{balance},
    frozen_amount = #{frozenAmount},
    version = #{newVersion},
    updated_at = #{updatedAt}
WHERE wallet_id = #{walletId}
  AND version = #{expectedVersion}
